from math import gcd
from itertools import combinations

def combinations_check(n, a):
    """Checks the divisibility condition for a specific pair (n, a)."""
    if n % 2 == 0 or n % 3 == 0 or n < 5:
        return None # Invalid starting point

    # Determine the range for a: ceil(n/3) <= a <= floor((n-1)/2)
    import math
    a_min = math.ceil(n / 3)
    a_max = math.floor((n - 1) / 2)

    if a_min > a_max:
        # Should not happen for n >= 5
        return True 

    for a in range(a_min, a_max + 1):
        k = n - 2 * a

        # Check k > 0 and k <= a (needed for binomial coefficient to be defined conventionally)
        if k <= 0 or k - 1 > a - 1:
            # k=1 case is handled below (k-1=0)
            if k == 1:
                continue # Always holds
            else:
                # This path implies k is outside the range where C(a-1, k-1) is positive.
                # Since a_max is floor((n-1)/2), k is always >= 1.
                # k-1 <= a-1 is equivalent to n-2a-1 <= a-1 => n <= 3a. Since a >= ceil(n/3), this holds.
                pass

        # Binomial coefficient: C(a-1, k-1)
        try:
            import math
            binom = math.comb(a - 1, k - 1)
        except AttributeError:
            # Fallback for older Python versions if math.comb isn't available
            from math import factorial
            try:
                binom = factorial(a - 1) // (factorial(k - 1) * factorial(a - k))
            except ValueError:
                # Should not happen given constraints
                continue 

        # Divisibility condition: k | C(a-1, k-1)
        if k > 0 and binom % k != 0:
            return False # Found a counterexample

    return True # Holds for all valid 'a'

# Search for solutions n < 200
solutions = []
for n in range(2, 200):
    if gcd(n, 6) == 1:
        if combinations_check(n, 0):
            solutions.append(n)

print(f"Solutions found: {solutions}")
print(f"Count: {len(solutions)}")
